      "item": "i01",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "五行相生关系由双方五行及作用方向确定，不以阴阳属性为成立条件；阴阳可用于进一步区分十神。"
        },
        {
          "dimension": "plain_language",
          "detail": "未解释“生”的含义，建议说明其表示一方对另一方的滋养、支持，如木生火，并明确谁生谁。"
        }
      ],
      "reason": "不单凭相生判断喜用神的提醒合理，但混淆了五行关系与阴阳的作用，且缺少实际释义。"
    },
    {
      "item": "i02",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "“耗”的关系不以双方阴阳为成立条件；在常见生克耗泄表述中，通常指“我克者”使我付出力量，须明确参照方。"
        },
        {
          "dimension": "plain_language",
          "detail": "未解释“耗”是如何形成的，建议以“我去克制对方，也会耗用自身力量”作白话说明，避免被理解为必然破财。"
        }
      ],
      "reason": "释义遗漏了“耗”的作用方向，并错误地将阴阳列为关系成立条件。"
    },
    {
      "item": "i03",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "五行“同类”指双方属于同一种五行，不要求阴阳相同；阴阳不同仍可为同类。"
        },
        {
          "dimension": "plain_language",
          "detail": "未直接说明“同类”的含义，建议补充“如甲木与乙木都属木，因此属于五行同类”。"
        }
      ],
      "reason": "“同类”的判断依据表述不准，且缺少面向普通用户的具体解释。"
    },
    {
      "item": "i04",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "“泄”通常从“我生者”的角度描述自身力量的输出，不以双方阴阳为成立条件，应明确参照方与相生方向。"
        },
        {
          "dimension": "plain_language",
          "detail": "未解释“泄”的含义，建议说明“自身生出另一五行，力量有所输出”，并避免将其直接等同于凶或损失。"
        }
      ],
      "reason": "未交代“泄”与“我生”的对应关系，且将阴阳误列为必要条件。"
    },
    {
      "item": "i05",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "五行相克关系由双方五行及作用方向确定，不以阴阳属性为成立条件；应明确谁克谁。"
        },
        {
          "dimension": "plain_language",
          "detail": "未解释“克”的含义，建议说明其表示制约、约束，如水克火，并提示相克本身不等于灾祸或不利。"
        }
      ],
      "reason": "不单凭相克判断喜用神的提醒合理，但关系成立条件不准，也缺少对“克”的白话解释。"
    }
  ]
}
